/**
 * A page's content stream, as Chromium writes it: its operators, and the painting that no marked content tags.
 * Chromium tags an element's content with an MCID (`/P <</MCID 3>> BDC ... EMC`), but leaves some painting out: the page's
 * background, the text generated by CSS (a slide's number), an emoji drawn as an image with its text in a fallback font.
 */

const paths = new Set(['m', 'l', 'c', 'v', 'y', 'h', 're']);
const paintings = new Set(['f', 'F', 'f*', 'S', 's', 'B', 'B*', 'b', 'b*', 'n']);
const texts = new Set(['Tj', 'TJ', "'", '"']);
const objects = new Set(['Do', 'sh', 'BI']);
// The operators that may come between two texts of a same run
const textState = new Set(['Td', 'TD', 'Tm', 'T*', 'Tf', 'Tc', 'Tw', 'Tz', 'TL', 'Ts', 'Tr', 'g', 'G', 'rg', 'RG', 'k', 'K', 'cs', 'CS', 'sc', 'SC', 'scn', 'SCN', 'gs']);

const isSpace = byte => byte === 0x20 || byte === 0x0a || byte === 0x0d || byte === 0x09 || byte === 0x0c || byte === 0x00;
const isDelimiter = byte => '()<>[]{}/%'.includes(String.fromCharCode(byte));
const escapes = { n: 0x0a, r: 0x0d, t: 0x09, b: 0x08, f: 0x0c };

/** A literal string's bytes, its escapes resolved; `index` is right after its opening parenthesis */
const literal = (bytes, index) => {
  const value = [];
  let depth = 1;
  while (index < bytes.length) {
    const byte = bytes[index++];
    if (byte === 0x5c) {
      const next = String.fromCharCode(bytes[index]);
      if (/[0-7]/.test(next)) {
        const octal = /^[0-7]{1,3}/.exec(String.fromCharCode(...bytes.subarray(index, index + 3)))[0];
        value.push(Number.parseInt(octal, 8) & 0xff);
        index += octal.length;
      } else if (next === '\r' || next === '\n') {
        index += next === '\r' && bytes[index + 1] === 0x0a ? 2 : 1;
      } else {
        value.push(escapes[next] ?? bytes[index]);
        index++;
      }
    } else if (byte === 0x28) {
      depth++;
      value.push(byte);
    } else if (byte === 0x29 && --depth === 0) {
      break;
    } else {
      value.push(byte);
    }
  }
  return { value: Uint8Array.from(value), end: index };
};

/**
 * The operators of a content stream, in order, each with its operands and its bytes' range, operands included:
 * strings as bytes, names without their slash, numbers as numbers; an array's or a dictionary's items flattened.
 */
export function operators(bytes) {
  const result = [];
  let operands = [];
  let start;
  let index = 0;
  while (index < bytes.length) {
    const byte = bytes[index];
    if (isSpace(byte)) {
      index++;
      continue;
    }
    if (byte === 0x25) {
      while (index < bytes.length && bytes[index] !== 0x0a && bytes[index] !== 0x0d) index++;
      continue;
    }
    start ??= index;
    if (byte === 0x28) {
      const string = literal(bytes, index + 1);
      operands.push({ string: string.value });
      index = string.end;
    } else if (byte === 0x3c && bytes[index + 1] !== 0x3c) {
      const end = bytes.indexOf(0x3e, index);
      const hex = String.fromCharCode(...bytes.subarray(index + 1, end)).replaceAll(/\s/g, '');
      operands.push({ string: Uint8Array.from((hex.length % 2 ? `${hex}0` : hex).match(/../g) ?? [], pair => Number.parseInt(pair, 16)) });
      index = end + 1;
    } else if (byte === 0x3c || byte === 0x3e) {
      index += 2;
    } else if (byte === 0x5b || byte === 0x5d || byte === 0x7b || byte === 0x7d) {
      index++;
    } else {
      const wordStart = byte === 0x2f ? index + 1 : index;
      index = wordStart;
      while (index < bytes.length && !isSpace(bytes[index]) && !isDelimiter(bytes[index])) index++;
      const word = String.fromCharCode(...bytes.subarray(wordStart, index));
      if (byte === 0x2f) operands.push({ name: word });
      else if (/^[+-]?(\d+\.?\d*|\.\d+)$/.test(word)) operands.push({ number: Number(word) });
      else if (word === 'true' || word === 'false' || word === 'null') operands.push({ keyword: word });
      else {
        // An inline image's data, up to its end
        if (word === 'BI') index = Buffer.from(bytes.buffer, bytes.byteOffset, bytes.length).indexOf('EI', index) + 2;
        result.push({ op: word, operands, start, end: index });
        operands = [];
        start = undefined;
      }
    }
  }
  return result;
}

/** A BDC's MCID, if it has one */
const mcidOf = ({ op, operands }) => {
  if (op !== 'BDC') return undefined;
  const index = operands.findIndex(operand => operand.name === 'MCID');
  return index === -1 ? undefined : operands[index + 1]?.number;
};

/**
 * The painting outside any tagging marked content, in units to mark, and the text shown in each MCID.
 * A unit is a path painted, an image or shading, a run of text shown, or a marked content sequence that doesn't tag
 * (Chromium's `/Span <</ActualText ...>>` around an emoji); `text` tells whether it shows text. Each unit also knows the
 * MCIDs right before and after it, its neighbors in the structure.
 * @param {Uint8Array} bytes The content stream
 * @param {(font: string, bytes: Uint8Array) => string} decode A string's text in a font of the page
 */
export function analyze(bytes, decode) {
  const units = [];
  const textByMcid = new Map();
  const stack = []; // the marked content sequences open: their MCID, or whether they are an artifact
  const fonts = [undefined]; // the font, saved and restored with the graphics state
  let lastMcid;
  let path; // the start of the path being built outside tagged content
  let run; // the text run being shown outside tagged content
  let container; // the marked content sequence that doesn't tag, outside tagged content
  const tagged = () => stack.some(entry => entry.mcid !== undefined || entry.artifact);
  const innerMcid = () => stack.findLast(entry => entry.mcid !== undefined)?.mcid;
  const add = unit => {
    unit.before = lastMcid;
    units.push(unit);
  };

  for (const operator of operators(bytes)) {
    const { op, operands, start, end } = operator;
    if (op === 'q') fonts.push(fonts.at(-1));
    else if (op === 'Q' && fonts.length > 1) fonts.pop();
    else if (op === 'Tf') fonts[fonts.length - 1] = operands[0]?.name;

    if (texts.has(op)) {
      const text = operands
        .filter(operand => operand.string)
        .map(operand => decode(fonts.at(-1), operand.string))
        .join('');
      const mcid = innerMcid();
      if (mcid !== undefined) textByMcid.set(mcid, (textByMcid.get(mcid) ?? '') + text);
      if (container) container.text = true;
    }

    if (container) {
      if (op === 'BDC' || op === 'BMC') container.depth++;
      else if (op === 'EMC' && --container.depth === 0) {
        add({ start: container.start, end, text: container.text });
        container = undefined;
      }
      continue;
    }
    if (op === 'BDC' || op === 'BMC') {
      run = undefined;
      path = undefined;
      const mcid = mcidOf(operator);
      const artifact = operands[0]?.name === 'Artifact';
      if (!tagged() && mcid === undefined && !artifact) {
        container = { start, depth: 1, text: false };
        continue;
      }
      stack.push({ mcid, artifact });
      if (mcid !== undefined) {
        lastMcid = mcid;
        for (const unit of units) unit.after ??= mcid;
      }
      continue;
    }
    if (op === 'EMC') {
      run = undefined;
      path = undefined;
      stack.pop();
      continue;
    }
    if (tagged()) continue;

    if (texts.has(op)) {
      if (run) {
        run.unit.end = end;
      } else {
        run = { unit: { start, end, text: true } };
        add(run.unit);
      }
    } else if (!textState.has(op)) {
      run = undefined;
    }
    if (paths.has(op)) path ??= start;
    else if (paintings.has(op)) {
      if (path !== undefined && op !== 'n') add({ start: path, end, text: false });
      path = undefined;
    } else if (objects.has(op)) {
      add({ start, end, text: false });
    }
  }
  return { units, textByMcid };
}

/** The content stream with marked content around each unit: `units` with their `open` operator, such as `/Artifact BMC` */
export function wrap(bytes, units) {
  const encoder = new TextEncoder();
  const parts = [];
  let last = 0;
  for (const { start, end, open } of units.toSorted((a, b) => a.start - b.start)) {
    parts.push(bytes.subarray(last, start), encoder.encode(`${open}\n`), bytes.subarray(start, end), encoder.encode('\nEMC'));
    last = end;
  }
  parts.push(bytes.subarray(last));
  return Buffer.concat(parts);
}
